fn largest_smallest_integers(arr: Vec<i8>) -> (Option<i8>, Option<i8>) {
    // If the slice is empty, both .max() and .min() will return None.
    // Otherwise, they return Some(&i8), so we use .copied() to turn it into Option<i8>.
    let max_opt = arr.iter().max().copied();
    let min_opt = arr.iter().min().copied();
    (max_opt, min_opt)
}

